group.p:
Example payload: {
    "parse_mode": "HTML",
    "text": "👋 BIENVENIDO \n\nHola, {{first_name}} {{last_name}} \n Soy el bot de soporte y gestión corporativa de Insumos Velardi.\n\nPara acceder a tus productos, pedidos, documentos y notificaciones en tiempo real, necesitas vincular tu cuenta con nosotros. \n\n Pulsa el botón de abajo para comenzar 👇",
    "reply_markup": {
        "inline_keyboard": [
        [
            {
            "text": "🔗 Vincular mi Cuenta",
            "callback_data": "start_registration"
            }
        ],
        [
            {
            "text": "📲 Abrir WhatsApp (+56 9 8251 0043)",
            "url": "https://wa.me/56982510043"
            }
        ],
        [
            {
            "text": "🌐 Sitio Web",
            "url": "https://www.velardi.cl"
            },
            {
            "text": "📸 Instagram",
            "url": "https://instagram.com/insumosvelardicl"
            }
        ]
        ]
    }}

Example payload: {
    "text": "✅ Registro completado\n\n   👤{{first_name}} {{last_name}}\n\n   📧 Email: {{email}} \n\n   🏷️ Usuario: {{telegram_username}} \n\n www.velardi.cl.\n\n Envía /menu para comenzar.",
    "parse_mode": "HTML",
    "reply_markup": {
        "inline_keyboard": [
        [
            {
            "text": "Opción A",
            "callback_data": "opcion_a"
            }
        ],
        [
            {
            "text": "Opción B",
            "callback_data": "opcion_b"
            }
        ],
        [
            {
            "text": "Hablar con soporte",
            "callback_data": "soporte"
            }
        ]
        ]
    }
    }

Example payload: 
    {
    "text": "Compárteme tu correo electrónico para crear tu cuenta y mantenerte al tanto  de todas las novedades y beneficios exclusivos 🚀",
    "parse_mode": "HTML",
    "reply_markup": {
        "force_reply": true,
        "selective": true,
        "input_field_placeholder": "@email.com"
    }
    }

Example payload: {
"text": "📱 Please enter your phone number.",
"parse_mode": "HTML",
"reply_markup": {
    "keyboard": [
    [
        {
        "text": "📱 Share my contact",
        "request_contact": true
        }
    ],
    [
        {
        "text": "✍️ Type manually"
        }
    ]
    ],
    "resize_keyboard": true,
    "one_time_keyboard": true
}
}

